sqlite3 -header -column ../data/current.db <<'SQL'
WITH ops AS (SELECT o.operation_id,s.service_code,o.opened_at_ms FROM logical_operations o JOIN service_routes r USING(route_id) JOIN services s USING(service_id) WHERE opened_at_ms>=1777629600000 AND opened_at_ms<1777633200000), agg AS (SELECT o.operation_id,count(a.attempt_id) attempts,sum(CASE WHEN f.is_success=0 THEN 1 ELSE 0 END) failed_attempts,max(a.attempt_no) max_no FROM ops o LEFT JOIN attempt_events a USING(operation_id) LEFT JOIN failure_codes f USING(code_id) GROUP BY o.operation_id), terminal AS (SELECT a.operation_id, f.is_success FROM attempt_events a JOIN failure_codes f USING(code_id) WHERE a.attempt_no=(SELECT max(x.attempt_no) FROM attempt_events x WHERE x.operation_id=a.operation_id)) SELECT o.service_code,count(*) operations,sum(a.attempts) attempts,sum(a.failed_attempts) failed_attempts,sum(CASE WHEN t.is_success=0 THEN 1 ELSE 0 END) terminal_failures,sum(CASE WHEN a.attempts>1 THEN 1 ELSE 0 END) retried_operations,count(DISTINCT ra.pool_id) physical_pools FROM ops o JOIN agg a USING(operation_id) JOIN terminal t USING(operation_id) JOIN service_routes r ON r.service_id=(SELECT service_id FROM services WHERE service_code=o.service_code) JOIN route_assignments ra ON ra.route_id=r.route_id AND o.opened_at_ms>=ra.effective_from_ms AND o.opened_at_ms<ra.effective_to_ms GROUP BY o.service_code;
SQL

