    "WITH ops AS (SELECT o.operation_id FROM logical_operations o WHERE o.opened_at_ms >= 1777629600000 AND o.opened_at_ms < 1777633200000), per_op AS (SELECT ops.operation_id, COUNT(a.attempt_id) AS attempts, SUM(CASE WHEN f.is_success = 0 THEN 1 ELSE 0 END) AS failed_attempts FROM ops LEFT JOIN attempt_events a ON a.operation_id = ops.operation_id LEFT JOIN failure_codes f ON f.code_id = a.code_id GROUP BY ops.operation_id), final_outcome AS (SELECT a.operation_id, f.is_success FROM attempt_events a JOIN failure_codes f ON f.code_id = a.code_id WHERE a.attempt_no = (SELECT MAX(a2.attempt_no) FROM attempt_events a2 WHERE a2.operation_id = a.operation_id)) SELECT COUNT(*) AS operations, SUM(p.attempts) AS attempts, SUM(p.failed_attempts) AS failed_attempts, SUM(CASE WHEN fo.is_success = 0 THEN 1 ELSE 0 END) AS terminal_failures, SUM(CASE WHEN p.attempts > 1 THEN 1 ELSE 0 END) AS retried_operations FROM per_op p JOIN final_outcome fo ON fo.operation_id = p.operation_id"
  ],
  "caveats": [
    "Failed attempts count individual unsuccessful tries, including failures followed by a successful retry; terminal failures count operations whose final attempt failed. They therefore have different units and are not interchangeable.",
    "Physical pools are counted by distinct pool_id from the route assignment effective at each operation's open time."
  ]
}

